import{_ as e,o as a,c as l,Q as i}from"./chunks/framework.a0e7c6b8.js";const b=JSON.parse('{"title":"性能优化","description":"","frontmatter":{},"headers":[],"relativePath":"articles/other/optimize.md","filePath":"articles/other/optimize.md"}'),o={name:"articles/other/optimize.md"},t=i('<h1 id="性能优化" tabindex="-1">性能优化 <a class="header-anchor" href="#性能优化" aria-label="Permalink to &quot;性能优化&quot;">​</a></h1><p>要了解前端性能优化,需要知道输入url到页面展示的整个过程，发生了什么，才能知道哪些地方可以优化。</p><h3 id="dns解析" tabindex="-1">DNS解析 <a class="header-anchor" href="#dns解析" aria-label="Permalink to &quot;DNS解析&quot;">​</a></h3><p>DNS解析就是将域名解析成IP地址，浏览器通过IP地址找到服务器。</p><h3 id="tcp连接" tabindex="-1">TCP连接 <a class="header-anchor" href="#tcp连接" aria-label="Permalink to &quot;TCP连接&quot;">​</a></h3><p>TCP连接就是浏览器和服务器之间的连接，浏览器通过TCP协议和服务器建立连接。</p><h3 id="发送http请求" tabindex="-1">发送HTTP请求 <a class="header-anchor" href="#发送http请求" aria-label="Permalink to &quot;发送HTTP请求&quot;">​</a></h3><p>浏览器通过HTTP协议向服务器发送请求，请求内容包括请求行、请求头、请求体。</p><h3 id="服务器处理请求" tabindex="-1">服务器处理请求 <a class="header-anchor" href="#服务器处理请求" aria-label="Permalink to &quot;服务器处理请求&quot;">​</a></h3><p>服务器接收到请求后，会根据请求的内容进行处理，处理完成后返回响应，响应内容包括状态行、响应头、响应体。</p><h3 id="浏览器解析响应" tabindex="-1">浏览器解析响应 <a class="header-anchor" href="#浏览器解析响应" aria-label="Permalink to &quot;浏览器解析响应&quot;">​</a></h3><p>浏览器接收到响应后，会根据响应的内容进行解析，解析完成后将页面展示给用户。</p><h2 id="http优化有两大方向" tabindex="-1">http优化有两大方向 <a class="header-anchor" href="#http优化有两大方向" aria-label="Permalink to &quot;http优化有两大方向&quot;">​</a></h2><ul><li>减少请求次数</li><li>减少请求大小</li></ul><h3 id="减少请求次数" tabindex="-1">减少请求次数 <a class="header-anchor" href="#减少请求次数" aria-label="Permalink to &quot;减少请求次数&quot;">​</a></h3><ol><li>合并文件，将多个CSS文件合并成一个CSS文件，将多个JS文件合并成一个JS文件。</li><li>压缩文件，将CSS文件、JS文件、图片文件进行压缩，减少文件大小。</li><li>懒加载，将页面中的图片、视频等资源进行懒加载，只有当用户滚动到页面底部时，才加载这些资源。</li><li>缓存，将CSS文件、JS文件、图片文件等进行缓存，当用户再次访问页面时，可以直接从缓存中获取资源，减少请求次数。</li></ol><h3 id="减少请求大小" tabindex="-1">减少请求大小 <a class="header-anchor" href="#减少请求大小" aria-label="Permalink to &quot;减少请求大小&quot;">​</a></h3><ol><li>压缩文件，将CSS文件、JS文件、图片文件进行压缩，减少文件大小。</li><li>使用CDN，将资源部署到CDN上，用户可以从离自己最近的服务器获取资源，减少请求时间。</li><li>使用HTTP/2，HTTP/2支持多路复用，可以同时发送多个请求，减少请求次数。</li></ol><h2 id="webpack优化方案" tabindex="-1">webpack优化方案 <a class="header-anchor" href="#webpack优化方案" aria-label="Permalink to &quot;webpack优化方案&quot;">​</a></h2><ol><li>使用<code>webpack-bundle-analyzer</code>插件，分析打包后的文件大小，找出需要优化的地方。</li><li>使用<code>code-splitting</code>，将代码分割成多个文件，按需加载，减少首次加载时间。</li><li>使用<code>tree-shaking</code>，去除未使用的代码，减少打包后的文件大小。</li><li>使用<code>webpack-parallel-uglify-plugin</code>插件，使用多核CPU进行代码压缩，提高压缩速度。</li><li>使用<code>webpack-dll-plugin</code>插件，将第三方库打包成DLL文件，避免每次打包时都重新打包第三方库。</li></ol><h2 id="图片优化" tabindex="-1">图片优化 <a class="header-anchor" href="#图片优化" aria-label="Permalink to &quot;图片优化&quot;">​</a></h2><ol><li>压缩图片，使用工具如TinyPNG、ImageOptim等。</li><li>使用CSS Sprite技术，将多张图片合并成一张图片，减少请求次数。</li><li>使用懒加载，只有当用户滚动到图片位置时，才加载图片。</li><li>base64编码，将图片转换为base64编码，减少请求次数。</li></ol><h2 id="浏览器缓存优化策略" tabindex="-1">浏览器缓存优化策略 <a class="header-anchor" href="#浏览器缓存优化策略" aria-label="Permalink to &quot;浏览器缓存优化策略&quot;">​</a></h2><ol><li>强缓存，通过设置<code>Cache-Control</code>和<code>Expires</code>头，告诉浏览器在指定时间内可以直接使用缓存，不需要向服务器发送请求。</li><li>协商缓存，通过设置<code>ETag</code>和<code>Last-Modified</code>头，告诉浏览器在指定时间内可以直接使用缓存，不需要向服务器发送请求，如果缓存失效，则向服务器发送请求，服务器根据<code>ETag</code>和<code>Last-Modified</code>判断是否需要更新缓存。</li></ol><h2 id="本地缓存优化策略" tabindex="-1">本地缓存优化策略 <a class="header-anchor" href="#本地缓存优化策略" aria-label="Permalink to &quot;本地缓存优化策略&quot;">​</a></h2><ol><li>使用<code>localStorage</code>和<code>sessionStorage</code>，将数据存储在浏览器中，减少请求次数。</li><li>使用<code>IndexedDB</code>，将大量数据存储在浏览器中，减少请求次数。</li><li>使用<code>Service Worker</code>，将数据缓存到浏览器中，减少请求次数。</li></ol><h2 id="css和js阻塞优化" tabindex="-1">css和js阻塞优化 <a class="header-anchor" href="#css和js阻塞优化" aria-label="Permalink to &quot;css和js阻塞优化&quot;">​</a></h2><ol><li>将CSS文件放在<code>&lt;head&gt;</code>标签中，将JS文件放在<code>&lt;body&gt;</code>标签的底部，避免CSS和JS阻塞页面渲染。</li><li>使用<code>async</code>和<code>defer</code>属性，将JS文件异步加载，避免阻塞页面渲染。</li><li>使用<code>CSS</code>预处理器，如Sass、Less等，将CSS代码分割成多个文件，按需加载，减少阻塞时间。</li></ol><h2 id="dom的优化原理和方案" tabindex="-1">DOM的优化原理和方案 <a class="header-anchor" href="#dom的优化原理和方案" aria-label="Permalink to &quot;DOM的优化原理和方案&quot;">​</a></h2><ol><li>减少DOM操作，DOM操作是昂贵的，尽量避免频繁的DOM操作。</li><li>使用虚拟DOM，虚拟DOM可以减少DOM操作，提高页面渲染性能。</li><li>使用<code>requestAnimationFrame</code>，将DOM操作放在下一次重绘之前，避免页面卡顿。</li><li>使用<code>CSS3</code>动画，避免使用JavaScript动画，因为JavaScript动画会阻塞页面渲染。</li><li>减少回流和重绘，回流和重绘是昂贵的，尽量避免频繁的回流和重绘。</li></ol>',30),d=[t];function r(c,h,s,n,p,S){return a(),l("div",null,d)}const m=e(o,[["render",r]]);export{b as __pageData,m as default};
